/// <summary>
/// Extension of clicked method
/// </summary>
public void clicked()
{
    FormRun formRun;
    FormDataSource priceDiscTableDS;

    next clicked();

    formRun = this.formRun();         
    priceDiscTableDS = formRun.dataHelper().FindDataSource(tableStr(PriceDiscTable));
    priceDiscTableDS.executeQuery();
}
